ter="8"><img src="/assets/cf/revisao-guiada/m03/CF-M03-C08.webp" alt="Revisão visual do capítulo 8: Quem vota: obrigatório, facultativo e inalistável" loading="lazy" decoding="async" width="1229" height="1536"><figcaption>Resumo visual — capítulo 8</figcaption></figure><section class="bc-m01-topic bc-apostila-topic" aria-labelledby="bc-guided-title-3-8">'), '<section class="bc-m01-topic bc-apostila-topic" aria-labelledby="bc-guided-title-3-9">', '<figure class="bc-editor-image bc-editor-image-full bc-review-infographic" data-bc-chapter="9"><img src="/assets/cf/revisao-guiada/m03/CF-M03-C09.webp" alt="Revisão visual do capítulo 9: Elegibilidade e idades mínimas" loading="lazy" decoding="async" width="1229" height="1536"><figcaption>Resumo visual — capítulo 9</figcaption></figure><section class="bc-m01-topic bc-apostila-topic" aria-labelledby="bc-guided-title-3-9">'), '<section class="bc-m01-topic bc-apostila-topic" aria-labelledby="bc-guided-title-3-10">', '<figure class="bc-editor-image bc-editor-image-full bc-review-infographic" data-bc-chapter="10"><img src="/assets/cf/revisao-guiada/m03/CF-M03-C10.webp" alt="Revisão visual do capítulo 10: Reeleição, desincompatibilização e inelegibilidades" loading="lazy" decoding="async" width="1229" height="1536"><figcaption>Resumo visual — capítulo 10</figcaption></figure><section class="bc-m01-topic bc-apostila-topic" aria-labelledby="bc-guided-title-3-10">'), '<section class="bc-m01-topic bc-apostila-topic" aria-labelledby="bc-guided-title-3-11">', '<figure class="bc-editor-image bc-editor-image-full bc-review-infographic" data-bc-chapter="11"><img src="/assets/cf/revisao-guiada/m03/CF-M03-C11.webp" alt="Revisão visual do capítulo 11: Perda, suspensão e anualidade eleitoral" loading="lazy" decoding="async" width="1229" height="1536"><figcaption>Resumo visual — capítulo 11</figcaption></figure><section class="bc-m01-topic bc-apostila-topic" aria-labelledby="bc-guided-title-3-11">'), '<section class="bc-apostila-sintese"', '<figure class="bc-editor-image bc-editor-image-full bc-review-infographic" data-bc-chapter="12"><img src="/assets/cf/revisao-guiada/m03/CF-M03-C12.webp" alt="Revisão visual do capítulo 12: Partidos políticos: criação, registro e coligações" loading="lazy" decoding="async" width="1229" height="1536"><figcaption>Resumo visual — capítulo 12</figcaption></figure><section class="bc-apostila-sintese"'), revision=revision+1, updated_at=NOW()
 WHERE content_id='reader:19pwkh3' AND revision=5
   AND position('<figure' in html)=0
   AND regexp_count(html, '<section class="bc-m01-topic bc-apostila-topic"')=12
 RETURNING content_id,revision,label,html
), history AS (
 INSERT INTO central_content_override_history(content_id,revision,label,html,archived_at)
 SELECT content_id,revision,label,html,NOW() FROM new_content
 ON CONFLICT (content_id,revision) DO NOTHING
 RETURNING content_id
)
SELECT (SELECT COUNT(*) FROM new_content) AS content_rows_updated,
       (SELECT COUNT(*) FROM history) AS history_rows_saved;
